// ─── DONNÉES GUIDE FireRed — Kanto ───────────────────────────────────────────
// Zones remplies chapitre par chapitre.
// Structure d'une zone :
// {
//   id: string,          // identifiant unique (correspond aux KANTO_NODES dans App.jsx)
//   name: string,        // nom affiché
//   type: 'town'|'route'|'cave'|'gym',
//   icon: string,        // emoji
//   tip: string,         // astuce courte
//   encounters: [        // rencontres Pokémon
//     { method: 'grass'|'cave'|'surf'|'fish', pokemon: [{ id, nameFr, rate }] }
//   ],
//   items: [             // objets à ramasser
//     { name, source, key?: true }
//   ],
//   checklist: [string], // tâches à cocher
//   gym?: {              // uniquement pour les zones avec arène
//     badgeId, leader, leaderTitle, specialty, team, weaknesses, strategy, tips, recommended
//   }
// }

export const TYPE_WEAK = {
  rock:     ['water','grass','fighting','ground','steel'],
  water:    ['electric','grass'],
  electric: ['ground'],
  grass:    ['fire','ice','poison','flying','bug'],
  ice:      ['fire','fighting','rock','steel'],
  fighting: ['flying','psychic','fairy'],
  poison:   ['ground','psychic'],
  ground:   ['water','grass','ice'],
  flying:   ['electric','ice','rock'],
  psychic:  ['bug','ghost','dark'],
  bug:      ['fire','flying','rock'],
  ghost:    ['ghost','dark'],
  dragon:   ['ice','dragon','fairy'],
  dark:     ['fighting','bug','fairy'],
  steel:    ['fire','fighting','ground'],
  fire:     ['water','ground','rock'],
  normal:   ['fighting'],
  fairy:    ['poison','steel'],
}

export function teamWeaknesses(team) {
  const set = new Set()
  team.forEach(p => p.types.forEach(t => (TYPE_WEAK[t] || []).forEach(w => set.add(w))))
  return [...set]
}

